/* ============================================================
   i18n helpers (same pattern proven in the previous build)
   ============================================================ */
const bi = (en, zh) => ({ en, zh });
function scored(options) {
  // options listed worst -> best; assign 0,25,50,75,100
  return options.map((o, i) => ({ ...o, score: Math.round((i / (options.length - 1)) * 100) }));
}
function scoredWithNA(options) {
  const real = options.slice(0, -1); // last is "Not applicable"
  const withScores = scored(real);
  return [...withScores, { ...options[options.length - 1], score: null, na: true }];
}
function reversed(options) {
  // options listed BEST -> WORST in the source questionnaire; reverse the score assignment
  const n = options.length;
  return options.map((o, i) => ({ ...o, score: Math.round(((n - 1 - i) / (n - 1)) * 100) }));
}

