function ageToBand(ageStr) {
  const age = parseInt(ageStr, 10);
  if (!age || isNaN(age)) return null;
  if (age < 35) return "Under 35";
  if (age <= 44) return "35–44";
  if (age <= 54) return "45–54";
  if (age <= 64) return "55–64";
  return "65 and above";
}
