/* ============================================================
   SCORING ENGINE — domain average (excluding N/A), weighted overall
   ============================================================ */
function computeDomainScores(answers) {
  const results = DOMAINS.map((d) => {
    const scores = d.drivers.map((q) => answers[q.id]).filter((v) => v !== undefined && v !== null);
    const answeredAll = d.drivers.every((q) => answers[q.id] !== undefined);
    const avg = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : null;
    return { ...d, score: avg, answeredAll };
  });
  const complete = results.every((r) => r.score !== null);
  const overall = complete ? Math.round(results.reduce((sum, r) => sum + r.score * r.weight, 0)) : null;
  return { domains: results, overall, complete };
}
