function Confetti() {
  const pieces = Array.from({ length: 28 });
  const colors = [C.blueLight, "#6EEBFF", "#B79CFF", "#7CF5A0", "#fff", "#5FC9E8"];
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none" }}>
      {pieces.map((_, i) => {
        const left = Math.random() * 100, delay = Math.random() * 0.5, duration = 2 + Math.random() * 1.5;
        const size = 6 + Math.random() * 8, color = colors[i % colors.length], rotate = Math.random() * 360;
        return (
          <div key={i} style={{ position: "absolute", top: "-5%", left: `${left}%`, width: size, height: size * 1.4, background: color, opacity: 0.9, transform: `rotate(${rotate}deg)`, animation: `confettiFall ${duration}s ${delay}s ease-in infinite`, borderRadius: 2 }} />
        );
      })}
    </div>
  );
}

