/* ============================================================
   FLOW STEP BUILDERS
   Order: Personalisation (P01-P03) -> 17 domain questions,
   grouped by domain -> Vitality Summary -> adaptive branch
   instruments -> Health Risk Profile (always, short) ->
   Health Foundation Profile (optional, skippable) -> celebration -> results
   ============================================================ */
const PERSONAL_STEPS = [
  { kind: "personal", id: "mainGoal", icon: "🎯", label: bi("Main Health Goal", "主要健康目标"), text: bi("What's your main health goal right now?", "你目前的主要健康目标是什么？"), options: MAIN_GOALS },
  { kind: "personal", id: "mainConcern", multi: true, icon: "📋", label: bi("Main Concern", "主要关注"), text: bi("What's your main concern right now? (select all that apply)", "你目前最主要的关注点是什么？（可多选）"), options: MAIN_CONCERNS },
];
const RISK_STEPS = [
  { kind: "risk", id: "smoking", icon: "🚬", label: bi("Smoking", "吸烟"), text: bi("Do you currently use tobacco products?", "你目前有使用烟草产品吗？"), options: SMOKING_OPTS },
  { kind: "risk", id: "alcohol", icon: "🍷", label: bi("Alcohol", "饮酒"), text: bi("How often do you consume alcoholic drinks?", "你多常饮用含酒精饮料？"), options: ALCOHOL_OPTS },
  { kind: "risk", id: "activity", icon: "🏃", label: bi("Physical Activity", "体力活动"), text: bi("In a typical week, how many days do you do moderate or vigorous physical activity?", "在典型的一周中，你有多少天进行中等或剧烈的体力活动？"), options: ACTIVITY_OPTS },
  { kind: "risk", id: "diet", icon: "🥗", label: bi("Diet Quality", "饮食质量"), text: bi("How often do you eat a balanced diet with vegetables, fruits and adequate protein?", "你多常摄取包含蔬菜、水果与足够蛋白质的均衡饮食？"), options: DIET_OPTS },
  { kind: "risk", id: "sleep", icon: "🌙", label: bi("Sleep Duration", "睡眠时长"), text: bi("On average, how many hours do you sleep per night?", "你平均每晚睡多少小时？"), options: SLEEP_OPTS },
];
const HEALTH_FOUNDATION_STEP = { kind: "foundation" };
const BASE_STEPS = [...PERSONAL_STEPS, ...DOMAIN_STEPS, ...RISK_STEPS, HEALTH_FOUNDATION_STEP];

function categoryKeyForStep(steps, step) {
  const s = steps[step];
  if (!s) return null;
  if (s.kind === "personal") return "personal";
  if (s.kind === "domain") return "domain-" + s.domain;
  if (s.kind === "branch") return "branch-" + s.instrumentKey;
  if (s.kind === "risk") return "risk";
  return "foundation";
}
function categoryInfoForStep(steps, step) {
  const s = steps[step];
  if (!s) return null;
  if (s.kind === "personal") return { label: bi("A Little About You", "关于你的一些基本资料"), icon: "👤", desc: bi("Just a few quick questions to personalise your results.", "只需几个简单问题，让结果更贴合你的情况。") };
  if (s.kind === "domain") { const d = DOMAINS.find((dd) => dd.key === s.domain); return { label: s.domainLabel, icon: s.icon, desc: d.intro, color: s.color }; }
  if (s.kind === "branch") { const instr = INSTRUMENTS[s.instrumentKey]; return { label: instr.name, icon: instr.icon, desc: instr.desc, color: DOMAIN_COLORS[instr.domain] }; }
  if (s.kind === "risk") return { label: bi("Lifestyle & Habits", "生活方式与习惯"), icon: "🌿", desc: bi("A few lifestyle questions that help us understand the full picture.", "几个生活方式问题，帮助我们全面了解你的状况。") };
  return { label: bi("Health Foundation (Optional)", "健康基础资料（可选）"), icon: "🩺", desc: bi("If you have recent numbers handy, great — otherwise skip and fill in anytime.", "如果你手边有最近的数据，很好——否则可以跳过，之后随时补充。") };
}

// Where the patient is, counted in SECTIONS rather than raw question number.
// Showing "63" to someone who was told the check-up is 17 questions is what made
// testers feel it dragged; "Section 4 of 6" is honest and finite.
function sectionPositionForStep(steps, step) {
  let count = 0, current = 1, prev = null;
  for (let i = 0; i < steps.length; i++) {
    const info = categoryInfoForStep(steps, i);
    const key = info ? t(info.label, "en") : "";
    if (key !== prev) { count++; prev = key; }
    if (i === step) current = count;
  }
  return { current, total: count };
}

