/* ============================================================
   DELIVERY MODE — every patient, clinic or online, receives this
   as a sent link (no physical clinic tablet). The only difference
   between the two is which link they were sent:
   ...?ref=clinic  -> Clinic mode: free, full report unlocked
                       immediately, Doctor/Clinic Dashboard tabs visible
   (anything else) -> Online mode (default): free teaser, Full
                       Report behind a paid unlock, no clinic-only tabs
   ============================================================ */
// Clinic mode unlocks the full report free — for a patient sitting in the
// waiting room. Tidier link: mvi.drstan.com.my/?clinic
// The older ?ref=clinic form still works so anything already printed or
// bookmarked does not break.
function detectClinicMode() {
  try {
    const q = new URLSearchParams(window.location.search);
    return q.has("clinic") || q.get("ref") === "clinic";
  } catch {
    return false;
  }
}
function detectAdminMode() {
  try {
    return new URLSearchParams(window.location.search).get("admin") === "1";
  } catch {
    return false;
  }
}
// A named login per staff member rather than one shared code. Still not
// real security (visible to anyone who reads the page's source) — a
// deterrent for now, genuine access control needs server-side auth.
// Admin access uses real Firebase Authentication. The UIDs below are the three
// accounts allowed into the Doctor/Admin Portal. A UID is NOT a secret — it is
// useless without that account's password — and the Firestore security rules
// enforce this exact same list server-side, so this list sitting in the public
// bundle grants nobody anything.
const ADMIN_UIDS = [
  "4C4qwZy2fmP7peLj96ozwj5dYKm2", // Prof. Stanley Chan
  "bg93q49kWNUVSimemitXV1QyEcq2", // Dr. Yap Lee Ming
  "ddFt4HsrmygRlHxhiyVCaXCGtk02", // Dr. Dharsyanth
];

/* ============================================================
   STORAGE — Cloud Firestore, ONE DOCUMENT PER RECORD.

   The previous design appended every patient into a SINGLE Firestore
   document as one long JSON string. That caused two serious faults:

     1. CEILING — at ~20 KB per patient against Firestore's 1 MiB
        document limit, writes began failing at roughly 50 patients.
     2. LOST RECORDS — saving meant read-the-whole-blob, append, write
        it back. Two patients finishing at the same moment meant one
        silently overwrote the other.

   Writing one document per record removes both. The 1 MiB limit now
   applies per patient (we use ~2% of it), and because nobody shares a
   document, concurrent writes cannot collide at all.

   Every read and write is authenticated. Patients are signed in
   anonymously — they never see a login — purely so the security rules
   have an identity to check. Rules allow a patient to CREATE their own
   record but never to READ anyone's.
   ============================================================ */
const FIREBASE_CONFIG = {
  apiKey: "AIzaSyDhVTqeKug2hfv6ZV8Z_mw4LN4IfAfdssc",
  authDomain: "dr-stan-mvi.firebaseapp.com",
  projectId: "dr-stan-mvi",
  storageBucket: "dr-stan-mvi.firebasestorage.app",
  messagingSenderId: "939033838830",
  appId: "1:939033838830:web:adc0a0b6c8606a9fa6dfff",
};
const COLL = {
  patients: "mvi_patients",
  submissions: "mvi_submissions",
  leads: "mvi_leads",
  progress: "mvi_progress",
};

function loadScript(src) {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) return resolve();
    const el = document.createElement("script");
    el.src = src; el.onload = resolve; el.onerror = reject;
    document.head.appendChild(el);
  });
}

let _fb = null;
let _fbFailed = false;

// A patient never sees a login screen. If nobody is signed in we sign them in
// anonymously. If an admin has already signed in with their email we leave that
// session alone — we never downgrade a real account back to anonymous.
function ensureSignedIn(auth) {
  return new Promise((resolve, reject) => {
    if (auth.currentUser) return resolve(auth.currentUser);
    const unsub = auth.onAuthStateChanged((u) => {
      unsub();
      if (u) return resolve(u);
      auth.signInAnonymously().then((c) => resolve(c.user)).catch(reject);
    });
  });
}

async function getFirebase() {
  if (_fbFailed) return null;
  if (_fb) { try { await ensureSignedIn(_fb.auth); } catch { return null; } return _fb; }
  try {
    if (!window.firebase || !window.firebase.firestore || !window.firebase.auth) {
      const withTimeout = (src) => Promise.race([
        loadScript(src),
        new Promise((_, reject) => setTimeout(() => reject(new Error("timed out")), 8000)),
      ]);
      await withTimeout("https://www.gstatic.com/firebasejs/10.7.0/firebase-app-compat.js");
      await withTimeout("https://www.gstatic.com/firebasejs/10.7.0/firebase-firestore-compat.js");
      await withTimeout("https://www.gstatic.com/firebasejs/10.7.0/firebase-auth-compat.js");
    }
    if (!window.firebase.apps.length) window.firebase.initializeApp(FIREBASE_CONFIG);
    const auth = window.firebase.auth();
    const db = window.firebase.firestore();
    await ensureSignedIn(auth);
    _fb = { db, auth };
    return _fb;
  } catch (e) {
    _fbFailed = true; // don't retry a broken config on every save
    return null;
  }
}

const store = {
  async put(coll, id, obj) {
    const fb = await getFirebase();
    if (!fb) throw new Error("storage unavailable");
    await fb.db.collection(coll).doc(String(id)).set(obj);
    return true;
  },
  async merge(coll, id, obj) {
    const fb = await getFirebase();
    if (!fb) throw new Error("storage unavailable");
    await fb.db.collection(coll).doc(String(id)).set(obj, { merge: true });
    return true;
  },
  // Newest first. Capped so the Doctor Portal stays fast and stays well inside
  // the free tier's daily read allowance.
  async list(coll, max = 400) {
    const fb = await getFirebase();
    if (!fb) throw new Error("storage unavailable");
    const snap = await fb.db.collection(coll).orderBy("ts", "desc").limit(max).get();
    return snap.docs.map((d) => d.data());
  },
};

function AdminPortal({ lang, setLang, onExit }) {
  const [authed, setAuthed] = useState(false);
  const [authedUser, setAuthedUser] = useState(null);
  const [userInput, setUserInput] = useState("");
  const [passInput, setPassInput] = useState("");
  const [passError, setPassError] = useState(false);
  const [records, setRecords] = useState([]);
  const [loadingRecords, setLoadingRecords] = useState(false);
  const [selected, setSelected] = useState(null);
  const [docView, setDocView] = useState("patient");
  const [view, setView] = useState("list"); // "list" | "clinic"
  const [submissions, setSubmissions] = useState([]);
  const [loadingAgg, setLoadingAgg] = useState(false);
  const [progress, setProgress] = useState([]);
  const [leads, setLeads] = useState([]);

  async function loadRecords() {
    setLoadingRecords(true);
    try {
      const list = await store.list(COLL.patients);
      setRecords(list); // store.list already returns newest first
    } catch { setRecords([]); }
    setLoadingRecords(false);
  }
  async function loadAggregate() {
    setLoadingAgg(true);
    try {
      setSubmissions(await store.list(COLL.submissions));
    } catch { setSubmissions([]); }
    try {
      setProgress(await store.list(COLL.progress));
    } catch { setProgress([]); }
    try {
      setLeads(await store.list(COLL.leads));
    } catch { setLeads([]); }
    setLoadingAgg(false);
  }
  useEffect(() => { if (authed) { loadRecords(); loadAggregate(); } }, [authed]);

  const [signingIn, setSigningIn] = useState(false);
  // Real Firebase Authentication. The old version compared against a list of
  // usernames and passcodes hard-coded into this file — which meant anyone who
  // opened the browser's developer tools could read them. Those are gone.
  async function doSignIn() {
    if (signingIn) return;
    setSigningIn(true); setPassError("");
    try {
      const fb = await getFirebase();
      if (!fb) throw new Error("Cannot reach the server — check your connection and try again.");
      const cred = await fb.auth.signInWithEmailAndPassword(userInput.trim(), passInput);
      if (!ADMIN_UIDS.includes(cred.user.uid)) {
        await fb.auth.signOut();
        throw new Error("That account is not authorised for the Doctor Portal.");
      }
      setAuthedUser({ name: cred.user.email, uid: cred.user.uid });
      setAuthed(true);
    } catch (e) {
      const code = e && e.code ? e.code : "";
      setPassError(
        /wrong-password|user-not-found|invalid-credential|invalid-email/.test(code)
          ? "Incorrect email or password — try again."
          : (e && e.message) || "Sign-in failed."
      );
    }
    setSigningIn(false);
  }
  async function doSignOut() {
    try { const fb = await getFirebase(); if (fb) await fb.auth.signOut(); } catch {}
    setAuthed(false); setAuthedUser(null); setUserInput(""); setPassInput("");
  }

  if (!authed) {
    return (
      <div style={{ maxWidth: 380, margin: "60px auto 0", padding: "0 20px" }}>
        <div style={{ textAlign: "center", marginBottom: 20 }}><Logo size={56} /></div>
        <Card>
          <div style={{ fontSize: 15, fontWeight: 800, marginBottom: 4 }}>🔒 Admin / Doctor Access</div>
          <div style={{ fontSize: 12, color: C.mid, marginBottom: 14, lineHeight: 1.5 }}>
            This area is for clinic staff only. Sign in with your registered email address to view patient results.
          </div>
          <input type="email" autoComplete="username" value={userInput} onChange={(e) => { setUserInput(e.target.value); setPassError(""); }} placeholder="Email address"
            style={{ width: "100%", padding: "14px", borderRadius: 10, background: "#fff", border: `1.5px solid ${C.border}`, color: C.ink, fontSize: 15, marginBottom: 8 }} />
          <input type="password" autoComplete="current-password" value={passInput} onChange={(e) => { setPassInput(e.target.value); setPassError(""); }}
            onKeyDown={(e) => { if (e.key === "Enter") doSignIn(); }} placeholder="Password"
            style={{ width: "100%", padding: "14px", borderRadius: 10, background: "#fff", border: `1.5px solid ${passError ? C.red : C.border}`, color: C.ink, fontSize: 15, marginBottom: 8 }} />
          {passError && <div style={{ fontSize: 12, color: C.red, marginBottom: 8, lineHeight: 1.45 }}>{passError}</div>}
          <button onClick={doSignIn} disabled={signingIn} style={{ width: "100%", padding: "14px", borderRadius: 10, background: `linear-gradient(135deg, ${C.blueDeep}, ${C.blue})`, border: "none", color: "#fff", fontWeight: 800, fontSize: 14, cursor: signingIn ? "default" : "pointer", opacity: signingIn ? 0.65 : 1 }}>
            {signingIn ? "Signing in…" : "Sign in"}
          </button>
          {onExit && (
            <button onClick={onExit} style={{ width: "100%", marginTop: 8, padding: "10px", borderRadius: 10, background: "none", border: "none", color: C.mid, fontSize: 12.5, cursor: "pointer" }}>
              ← Back to patient assessment
            </button>
          )}
        </Card>
      </div>
    );
  }

  if (selected) {
    // Every stored patient record already holds the complete results object, so
    // the patient's own report can be re-rendered here exactly as they saw it —
    // and printed for a walk-in without them paying anything.
    const patientDemo = { name: selected.patientName, age: selected.patientAge, phone: selected.patientPhone };
    return (
      <div id={docView === "patient" ? "full-report-print" : undefined} style={{ maxWidth: 640, margin: "0 auto", padding: "20px 20px 60px" }}>
        <style>{MVI_PRINT_CSS}</style>
        <div className="no-print">
          <TopBar lang={lang} setLang={setLang} showLogo={false} />
          <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
            <button onClick={() => setSelected(null)} style={{ padding: "10px 16px", borderRadius: 10, background: C.panel2, border: `1px solid ${C.border}`, color: C.blueDeep, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
              ← Back to patient list
            </button>
            <button onClick={() => window.print()} style={{ padding: "10px 16px", borderRadius: 10, background: `linear-gradient(135deg, ${C.blueDeep}, ${C.blue})`, border: "none", color: "#fff", fontWeight: 800, fontSize: 13, cursor: "pointer" }}>
              ⤓ Print / Save as PDF
            </button>
          </div>
          <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
            {[{ k: "patient", label: "Patient report" }, { k: "doctor", label: "Doctor dashboard" }].map((o) => {
              const on = docView === o.k;
              return (
                <button key={o.k} onClick={() => setDocView(o.k)} style={{ flex: 1, padding: "11px", borderRadius: 11, cursor: "pointer", fontWeight: 800, fontSize: 13, background: on ? `linear-gradient(135deg, ${C.blueDeep}, ${C.blue})` : C.panel, color: on ? "#fff" : C.blueDeep, border: `1.5px solid ${on ? C.blueDeep : C.border}` }}>
                  {o.label}
                </button>
              );
            })}
          </div>
          <div style={{ fontSize: 11, color: C.dim, marginBottom: 14, lineHeight: 1.5 }}>
            {docView === "patient"
              ? "This is exactly what the patient sees in their full report. Print it for a clinic patient — no payment involved."
              : "Clinical view — synthesis, investigations and discussion points. Not shown to the patient."}
          </div>
        </div>
        {docView === "patient"
          ? <FullReportPage results={selected} demo={patientDemo} lang={lang} setLang={setLang} onBack={() => setSelected(null)} embedded />
          : <DoctorDashboard results={selected} demo={patientDemo} lang={lang} />}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: 640, margin: "0 auto", padding: "20px 20px 60px" }}>
      <TopBar lang={lang} setLang={setLang} showLogo={false} />
      <div style={{ textAlign: "center", marginBottom: 14 }}><Logo size={50} /></div>
      <div style={{ textAlign: "center", fontSize: 11.5, color: C.mid, marginBottom: 10 }}>
        Signed in as <b>{authedUser.name}</b>
        <button onClick={doSignOut} style={{ marginLeft: 10, padding: "4px 10px", borderRadius: 8, background: C.panel2, border: `1px solid ${C.border}`, color: C.blueDeep, fontWeight: 700, fontSize: 11, cursor: "pointer" }}>Sign out</button>
      </div>
      <div style={{ display: "flex", gap: 4, marginBottom: 20, background: C.panel2, borderRadius: 12, padding: 4 }}>
        {[{ k: "list", label: "Patient Results" }, { k: "clinic", label: "Clinic Dashboard" }].map((tb) => (
          <button key={tb.k} onClick={() => setView(tb.k)}
            style={{ flex: 1, padding: "10px 4px", borderRadius: 9, background: view === tb.k ? "#fff" : "transparent", boxShadow: view === tb.k ? "0 2px 6px rgba(11,92,171,0.15)" : "none",
              border: "none", color: view === tb.k ? C.blueDeep : C.mid, fontSize: 12.5, fontWeight: 800, cursor: "pointer", fontFamily: "inherit" }}>
            {tb.label}
          </button>
        ))}
      </div>
      {view === "list" && (
        loadingRecords ? <div style={{ color: C.dim, fontSize: 14 }}>Loading…</div> :
        records.length === 0 ? <div style={{ color: C.dim, fontSize: 14, textAlign: "center", padding: "40px 0" }}>No patient results yet.</div> :
        records.map((r) => {
          const cat = r.domainResults ? vitalityCategory(r.domainResults.overall) : null;
          return (
            <Card key={r.id} onClick={() => setSelected(r)} style={{ marginBottom: 10, cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ fontSize: 14, fontWeight: 700 }}>{r.patientName || "—"}</div>
                <div style={{ fontSize: 11.5, color: C.mid }}>{r.patientPhone} · {new Date(r.ts).toLocaleDateString()} · {r.mode}</div>
              </div>
              {cat && <div style={{ fontSize: 18, fontWeight: 900, color: cat.color }}>{r.domainResults.overall}</div>}
            </Card>
          );
        })
      )}
      {view === "clinic" && <ClinicDashboard submissions={submissions} loading={loadingAgg} lang={lang} progress={progress} leads={leads} />}
    </div>
  );
}

export default function App() {
  // Remembered across visits so a returning patient is not asked twice.
  const [lang, setLang] = useState(() => {
    try { const v = localStorage.getItem("mvi_lang"); if (v === "en" || v === "zh" || v === "ms") return v; } catch {}
    return "en";
  });
  // Always shown. This is the first thing anyone sees and it is how they are
  // told what MVI is and who built it, so it is not skipped for returning
  // visitors — the remembered language only pre-selects, it never bypasses.
  const [langChosen, setLangChosen] = useState(false);
  function chooseLanguage(code) {
    setLang(code);
    try { localStorage.setItem("mvi_lang", code); } catch {}
    setLangChosen(true);
  }
  const [stage, setStage] = useState("home");
  const [isClinicMode] = useState(detectClinicMode);
  const [isAdminMode] = useState(detectAdminMode);
  const [adminOpenedManually, setAdminOpenedManually] = useState(false);
  const showAdmin = isAdminMode || adminOpenedManually;
  const [appReady, setAppReady] = useState(false);
  const [sessionId] = useState(() => `s_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`);
  const [resumeAvailable, setResumeAvailable] = useState(false);
  const [resumeDismissed, setResumeDismissed] = useState(false);

  // A branded loading moment instead of a blank flash — waits briefly for
  // the display font to finish loading (or a short max wait, whichever
  // comes first) so the first thing a visitor sees is never an unstyled flash.
  useEffect(() => {
    let done = false;
    const finish = () => { if (!done) { done = true; setAppReady(true); } };
    try {
      if (document.fonts && document.fonts.ready) document.fonts.ready.then(finish);
      else finish();
    } catch { finish(); }
    const maxWait = setTimeout(finish, 700);
    return () => clearTimeout(maxWait);
  }, []);

  // Detect returning from Stripe's hosted payment page (configured to
  // redirect back with ?paid=1) and restore the result that was stashed
  // in localStorage right before the redirect out.
  useEffect(() => {
    try {
      const paid = new URLSearchParams(window.location.search).get("paid") === "1";
      if (!paid) return;
      const stashed = localStorage.getItem("mvi_pending_unlock");
      if (!stashed) return;
      const restored = JSON.parse(stashed);
      setFinalResults(restored);
      setFullReportUnlocked(true);
      setStage("fullreport");
      localStorage.removeItem("mvi_pending_unlock");
    } catch { /* nothing to restore, or storage unavailable — just start normally */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const [demo, setDemo] = useState({ name: "", age: "", phone: "", email: "", consent: false });
  const [answers, setAnswers] = useState({ personal: {}, domains: {} });
  const [branchAnswers, setBranchAnswers] = useState({});
  const [risk, setRisk] = useState({});
  const [foundation, setFoundation] = useState({ height: "", weight: "", waist: "", bpSys: "", bpDia: "", hba1c: "", testosterone: "" });
  const [flowSteps, setFlowSteps] = useState(BASE_STEPS);
  const [step, setStep] = useState(0);
  const [saveState, setSaveState] = useState("idle");
  const [leadId, setLeadId] = useState(null);
  const [transitionInfo, setTransitionInfo] = useState(null);
  const [pendingStep, setPendingStep] = useState(null);
  const [celebrating, setCelebrating] = useState(false);
  const [vitalitySummary, setVitalitySummary] = useState(null);
  const [aiInterpretation, setAiInterpretation] = useState(null);
  const [finalResults, setFinalResults] = useState(null);
  const [fullReportUnlocked, setFullReportUnlocked] = useState(false);

  // Resume-if-interrupted: check for a saved in-progress assessment on this
  // same device (never sent anywhere — just this browser's own storage).
  useEffect(() => {
    try {
      const saved = localStorage.getItem("mvi_resume_v1");
      if (saved) setResumeAvailable(true);
    } catch { /* no localStorage available — resume just won't be offered */ }
  }, []);

  // Autosave progress to this device only, while actively answering —
  // lets a patient close the tab and pick up where they left off.
  useEffect(() => {
    if (stage !== "intake") return;
    try {
      const snapshot = { demo, answers, branchAnswers, risk, foundation, step, ts: Date.now() };
      localStorage.setItem("mvi_resume_v1", JSON.stringify(snapshot));
    } catch { /* best-effort — never blocks the patient's flow */ }
  }, [stage, demo, answers, branchAnswers, risk, foundation, step]);

  // Drop-off visibility — a lightweight record of how far this session got,
  // updated as they progress. If they never finish, this is what shows an
  // admin exactly where the assessment lost them.
  useEffect(() => {
    if (stage !== "intake") return;
    (async () => {
      try {
        // One document per session, keyed by sessionId. This is a plain write
        // with no read first — it used to read and rewrite the entire progress
        // list on every single question.
        await store.put(COLL.progress, sessionId, {
          sessionId, step, totalSteps: flowSteps.length, ts: Date.now(),
          mode: isClinicMode ? "clinic" : "online",
        });
      } catch { /* best-effort — never blocks the patient's flow */ }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stage, step]);

  function resumeSession() {
    try {
      const saved = JSON.parse(localStorage.getItem("mvi_resume_v1"));
      if (!saved) return;
      setDemo(saved.demo); setAnswers(saved.answers); setBranchAnswers(saved.branchAnswers);
      setRisk(saved.risk); setFoundation(saved.foundation); setStep(saved.step);
      setResumeDismissed(true);
      setStage("intake");
    } catch { /* if this fails, just start fresh */ }
  }
  function dismissResume() {
    try { localStorage.removeItem("mvi_resume_v1"); } catch {}
    setResumeAvailable(false); setResumeDismissed(true);
  }

  const s = flowSteps[step];

  function advanceOrTransition(nextStep, steps) {
    if (categoryKeyForStep(steps, nextStep) !== categoryKeyForStep(steps, step)) {
      setPendingStep(nextStep);
      setTransitionInfo(categoryInfoForStep(steps, nextStep));
    } else {
      setStep(nextStep);
    }
  }
  function confirmTransition() { setTransitionInfo(null); if (pendingStep !== null) { setStep(pendingStep); setPendingStep(null); } }
  function goBack() { if (step > 0) setStep(step - 1); }

  function goNext(latestAnswers, latestBranchAnswers) {
    const curAnswers = latestAnswers || answers;
    const curBranchAnswers = latestBranchAnswers || branchAnswers;
    let steps = flowSteps;

    // Just finished the 17 domain questions — pause on a summary screen, then build adaptive branch steps
    const lastDomainIndex = PERSONAL_STEPS.length + DOMAIN_STEPS.length - 1;
    if (step === lastDomainIndex && steps[lastDomainIndex + 1]?.kind === "risk" && !vitalitySummary) {
      const dr = computeDomainScores(curAnswers.domains);
      const priorities = runPriorityAlgorithm(dr.domains, curAnswers.personal.mainConcern, curAnswers.domains);
      const { fired } = buildBranchSteps({ energy: dr.domains.find((d) => d.key === "energy")?.score ?? 100, physical: dr.domains.find((d) => d.key === "physical")?.score ?? 100, mental: dr.domains.find((d) => d.key === "mental")?.score ?? 100 }, curAnswers.domains);
      // Prof. Stanley: let the patient choose whether to go deeper. The single
      // top-priority area runs automatically (that is the one the result hangs
      // on); everything else is offered, opted out of by default. This is what
      // stops a "17 question" check-up quietly turning into 80.
      // IIEF-5, IPSS and ADAM are short and clinically central, so whenever the
      // answers trigger them they simply run — no asking. DASS-21 and DASI are
      // the long ones and feed nothing in the MVI score, so those two are the
      // only ones ever offered as a choice.
      const ALWAYS_RUN = ["iief5", "ipss", "adam"];
      const autoKeys = fired.filter((k) => ALWAYS_RUN.includes(k));
      const optionalKeys = fired.filter((k) => !ALWAYS_RUN.includes(k));
      setVitalitySummary({ overall: dr.overall, priorities, autoKeys, optionalKeys });
      return;
    }

    if (step < steps.length - 1) {
      advanceOrTransition(step + 1, steps);
    } else {
      finish(curAnswers, curBranchAnswers);
    }
  }
  function continueFromVitalitySummary(chosenOptionalKeys) {
    const { autoKeys, optionalKeys } = vitalitySummary;
    const chosen = chosenOptionalKeys || [];
    // Keep the original trigger order rather than the order they were ticked.
    const keys = [...autoKeys, ...optionalKeys.filter((k) => chosen.includes(k))];
    const branchSteps = stepsForInstruments(keys);
    let steps = flowSteps;
    const lastDomainIndex = PERSONAL_STEPS.length + DOMAIN_STEPS.length - 1;
    if (branchSteps.length > 0 && steps[lastDomainIndex + 1]?.kind === "risk") {
      steps = [...steps.slice(0, lastDomainIndex + 1), ...branchSteps, ...steps.slice(lastDomainIndex + 1)];
      setFlowSteps(steps);
    }
    setVitalitySummary(null);
    advanceOrTransition(step + 1, steps);
  }

  function pickPersonal(id, val) {
    const next = { ...answers, personal: { ...answers.personal, [id]: val } };
    setAnswers(next);
    setTimeout(() => goNext(next, null), 220);
  }
  function pickPersonalMulti(id, val) {
    setAnswers((a) => {
      const cur = a.personal[id] || [];
      const has = cur.includes(val);
      const nextList = has ? cur.filter((v) => v !== val) : [...cur, val];
      return { ...a, personal: { ...a.personal, [id]: nextList } };
    });
  }
  function pickDomain(id, val) {
    const next = { ...answers, domains: { ...answers.domains, [id]: val === "NA" ? null : val } };
    setAnswers(next);
    setTimeout(() => goNext(next, null), 220);
  }
  function pickRisk(id, val) {
    setRisk((r) => ({ ...r, [id]: val }));
    setTimeout(() => goNext(null, null), 220);
  }
  function pickBranch(instrumentKey, itemId, val) {
    const next = { ...branchAnswers, [instrumentKey]: { ...(branchAnswers[instrumentKey] || {}), [itemId]: val } };
    setBranchAnswers(next);
    setTimeout(() => goNext(null, next), 220);
  }

  function finish(latestAnswers, latestBranchAnswers) {
    // Show the celebration screen with the button visible right away, and
    // build the report synchronously alongside it — no network call, no
    // timer, no separate "ready" flag for anything to get stuck on.
    setCelebrating(true); setSaveState("saving");
    try { localStorage.removeItem("mvi_resume_v1"); } catch {} // completed — no longer "in progress"
    // Only trust latestAnswers if it's genuinely shaped like answers data —
    // guards against any handler ever accidentally passing something else
    // (like a click event) straight through.
    const looksValid = (x) => x && typeof x === "object" && x.personal && x.domains;
    const a = looksValid(latestAnswers) ? latestAnswers : answers;
    const ba = (latestBranchAnswers && typeof latestBranchAnswers === "object") ? latestBranchAnswers : branchAnswers;
    const ageGroupBand = ageToBand(demo.age);
    let dr, priorities, branchResults, bmi, fullResultsForRecord;

    try {
      dr = computeDomainScores(a.domains);
      priorities = runPriorityAlgorithm(dr.domains, a.personal.mainConcern, a.domains);
      branchResults = Object.keys(ba).filter((k) => Object.keys(ba[k] || {}).length > 0).map((k) => ({ key: k, name: INSTRUMENTS[k].name, ...scoreInstrument(k, ba) }));
      const h = parseFloat(foundation.height) / 100, w = parseFloat(foundation.weight);
      bmi = h && w ? +(w / (h * h)).toFixed(1) : null;

      const report = generateOfflineReport({
        domainResults: dr, priorities, rawAnswers: a.domains, branchResults, risk, ageGroup: ageGroupBand, lang,
      });
      const clinicalSynthesis = buildClinicalSynthesis({
        domainResults: dr, priorities, branchResults, risk, bmi, ageGroup: ageGroupBand, lang,
      });
      setAiInterpretation(report);
      const results = {
        domainResults: dr, priorities, ai: report, clinicalSynthesis, foundation, bmi, risk, rawAnswers: a.domains,
        branchResults, triggeredNames: branchResults.map((r) => r.key),
        ageGroup: ageGroupBand, mainGoal: a.personal.mainGoal, mainConcern: a.personal.mainConcern,
      };
      setFinalResults(results);
      fullResultsForRecord = results;
      // Clinic-mode reports are free and unlocked immediately — the online
      // paywall only applies when this patient was sent the public link.
      if (isClinicMode) setFullReportUnlocked(true);
    } catch (e) {
      // Belt-and-braces: whatever went wrong above, tapping the button must
      // still produce something. This fallback deliberately never touches
      // 'a' again (that's what may have caused the original failure) — it
      // only uses 'answers', the always-safe component state.
      const safeDr = dr || { domains: DOMAINS.map((d) => ({ ...d, score: 0 })), overall: 0, complete: false };
      setFinalResults({
        domainResults: safeDr, priorities: priorities || [],
        ai: { summary: "Your report is ready.", strengths: [], opportunities: [], actionPlan: { maintain: "", optimise: "", exploreFurther: "" }, doctorSummary: "" },
        clinicalSynthesis: { investigations: [], followUp: [], discussionPoints: [], differentials: [], lookFor: [], management: [] },
        foundation, bmi: bmi || null, risk, rawAnswers: answers.domains, branchResults: branchResults || [], triggeredNames: [],
        ageGroup: ageGroupBand, mainGoal: answers.personal.mainGoal, mainConcern: answers.personal.mainConcern,
      });
    }

    (async () => {
      try {
        const record = {
          id: `sub_${Date.now()}`, ts: Date.now(), overall: dr ? dr.overall : null, domains: dr ? dr.domains : [],
          flagCount: (branchResults || []).length, topPriority: priorities && priorities[0] ? priorities[0].key : null,
          ageGroup: ageGroupBand, mode: isClinicMode ? "clinic" : "online", consent: !!demo.consent,
        };
        await store.put(COLL.submissions, record.id, record);
        setSaveState("saved");
      } catch (e) {
        // Never swallow this. A failed save used to be invisible to both the
        // patient and the clinic; now it surfaces on the results screen.
        console.error("MVI: submission save failed", e);
        setSaveState("error");
      }
    })();

    // Lead capture — a business contact record, separate from the research
    // dataset above. Saved for every completed assessment regardless of the
    // research consent choice, since the patient already gave this contact
    // information directly on the demographics page.
    (async () => {
      try {
        const lead = {
          id: `lead_${Date.now()}`, ts: Date.now(), name: demo.name, phone: demo.phone, email: demo.email || "",
          overall: dr ? dr.overall : null, mode: isClinicMode ? "clinic" : "online", purchased: isClinicMode,
        };
        setLeadId(lead.id);
        await store.put(COLL.leads, lead.id, lead);
      } catch (e) { console.error("MVI: lead save failed", e); }
    })();

    // Full patient record — this is what the Admin/Doctor Portal reads. The
    // patient never sees this data again after this point; only someone who
    // passes the admin passcode gate can look it up.
    (async () => {
      try {
        if (!fullResultsForRecord) return;
        const record = { id: `pat_${Date.now()}`, ts: Date.now(), patientName: demo.name, patientPhone: demo.phone, patientAge: demo.age,
          mode: isClinicMode ? "clinic" : "online", ...fullResultsForRecord };
        await store.put(COLL.patients, record.id, record);
      } catch (e) {
        console.error("MVI: patient record save failed", e);
        setSaveState("error");
      }
    })();
  }
  function viewReport() { setCelebrating(false); setStage("results"); }
  // The lead row is written when the assessment finishes, before we have any
  // contact details. This fills them in once the patient supplies them.
  async function saveContactDetails() {
    try {
      if (!leadId) return;
      await store.merge(COLL.leads, leadId, {
        name: demo.name, phone: demo.phone, email: demo.email || "",
        channel: demo.channel || "whatsapp", contactedAt: Date.now(),
      });
    } catch (e) { console.error("MVI: contact save failed", e); }
  }
  async function markLeadPurchased() {
    try {
      if (!leadId) return;
      await store.merge(COLL.leads, leadId, { purchased: true });
    } catch (e) { console.error("MVI: lead update failed", e); }
  }

  function restart() {
    setDemo({ name: "", age: "", phone: "", email: "", consent: false });
    setFullReportUnlocked(false);
    setAnswers({ personal: {}, domains: {} }); setBranchAnswers({}); setRisk({});
    setFoundation({ height: "", weight: "", waist: "", bpSys: "", bpDia: "", hba1c: "", testosterone: "" });
    setFlowSteps(BASE_STEPS); setStep(0); setStage("home"); setSaveState("idle");
    setVitalitySummary(null); setAiInterpretation(null); setFinalResults(null);
    setResumeAvailable(false); setResumeDismissed(false);
    try { localStorage.removeItem("mvi_resume_v1"); } catch {}
  }

  let isAnswered = false, needsManualButton = s?.kind === "foundation" || (s?.kind === "personal" && s.multi);
  const requireAnswer = s?.kind === "personal" && s.multi;
  if (s?.kind === "personal") isAnswered = s.multi ? (answers.personal[s.id] || []).length > 0 : answers.personal[s.id] !== undefined;
  else if (s?.kind === "domain") isAnswered = answers.domains[s.id] !== undefined;
  else if (s?.kind === "risk") isAnswered = risk[s.id] !== undefined;
  else if (s?.kind === "branch") isAnswered = (branchAnswers[s.instrumentKey] || {})[s.id] !== undefined;

  return (
    <div style={{ minHeight: "100vh", background: "#fff", color: C.ink, fontFamily: "'Inter', system-ui, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800;900&family=Inter:wght@400;500;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; } body { margin: 0; }
        h1,h2,.disp { font-family: 'Poppins', sans-serif; }
        .opt-btn { transition: all 0.12s ease; }
        .opt-btn:active { transform: scale(0.98); }
        @keyframes shimmer { 0% { background-position: -150px 0; } 100% { background-position: 250px 0; } }
        .bar-fill { background-image: linear-gradient(90deg, ${C.blue}, ${C.blueLight}, ${C.blue}); background-size: 250px 100%; animation: shimmer 1.8s linear infinite; box-shadow: 0 0 14px ${C.blue}66; }
        @keyframes glowPulse { 0%,100% { box-shadow: 0 0 0px ${C.blue}00; } 50% { box-shadow: 0 0 16px ${C.blue}55; } }
        .glow-pulse { animation: glowPulse 2.2s ease-in-out infinite; }
        @keyframes celebPop { 0% { transform: scale(0) rotate(-30deg); opacity: 0; } 55% { transform: scale(1.3) rotate(10deg); } 75% { transform: scale(0.9) rotate(-5deg); } 100% { transform: scale(1) rotate(0); opacity: 1; } }
        @keyframes confettiFall { 0% { transform: translateY(0) rotate(0deg); opacity: 1; } 100% { transform: translateY(110vh) rotate(540deg); opacity: 0.3; } }
        @keyframes bounceIn { 0% { transform: scale(0) rotate(-15deg); opacity: 0; } 50% { transform: scale(1.25) rotate(8deg); } 75% { transform: scale(0.92) rotate(-4deg); } 100% { transform: scale(1) rotate(0); opacity: 1; } }
        @keyframes blinkPulse { 0%,100% { box-shadow: 0 10px 26px rgba(0,0,0,0.25); transform: scale(1); } 50% { box-shadow: 0 10px 34px rgba(255,255,255,0.5); transform: scale(1.04); } }
        .blink-btn { animation: blinkPulse 1.3s ease-in-out infinite; }
        @keyframes dotPulse { 0%,80%,100% { opacity: 0.25; transform: scale(0.8); } 40% { opacity: 1; transform: scale(1); } }
        .dot { width: 8px; height: 8px; border-radius: 50%; background: #fff; display: inline-block; animation: dotPulse 1.1s ease-in-out infinite; }
        .loading-dot { width: 8px; height: 8px; border-radius: 50%; background: ${C.blueDeep}; display: inline-block; animation: dotPulse 1.1s ease-in-out infinite; }
        @keyframes magicGlow { 0%,100% { box-shadow: 0 0 18px 2px rgba(110,235,255,0.55), 0 10px 30px rgba(0,0,0,0.3); background-position: 0% 50%; } 50% { box-shadow: 0 0 34px 8px rgba(183,156,255,0.75), 0 10px 30px rgba(0,0,0,0.3); background-position: 100% 50%; } }
        .magic-btn { animation: magicGlow 1.8s ease-in-out infinite; transition: transform 0.15s ease; }
        .magic-btn:active { transform: scale(0.96); }
        @keyframes mviGlow { 0%,100% { text-shadow: 0 0 14px rgba(110,235,255,0.65), 0 0 32px rgba(110,235,255,0.4); } 50% { text-shadow: 0 0 26px rgba(110,235,255,1), 0 0 52px rgba(110,235,255,0.7); } }
        .mvi-glow { animation: mviGlow 2.4s ease-in-out infinite; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        input:focus { outline: none; border-color: ${C.blueDeep} !important; }
      `}</style>
      {showAdmin ? (
        <AdminPortal lang={lang} setLang={setLang} onExit={isAdminMode ? null : () => setAdminOpenedManually(false)} />
      ) : !langChosen ? (
        <LanguageGate onPick={chooseLanguage} />
      ) : (
      <div style={{ maxWidth: 640, margin: "0 auto", padding: stage === "intake" ? "10px 16px 0" : "20px 20px 60px", height: stage === "intake" ? "100dvh" : "auto", display: stage === "intake" ? "flex" : "block", flexDirection: "column", overflow: stage === "intake" ? "hidden" : "visible", boxSizing: "border-box" }}>
        {stage === "home" && resumeAvailable && !resumeDismissed && (
          <div style={{ maxWidth: 640, margin: "16px auto 0", background: C.panel2, border: `1.5px solid ${C.blueDeep}`, borderRadius: 14, padding: "14px 16px", display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ flex: 1, fontSize: 12.5, color: C.ink }}>{tr(lang, "You have an assessment in progress on this device.", "此设备上有一份尚未完成的评估。")}</div>
            <button onClick={resumeSession} style={{ padding: "8px 14px", borderRadius: 8, background: C.blueDeep, border: "none", color: "#fff", fontWeight: 700, fontSize: 12, cursor: "pointer" }}>{tr(lang, "Resume", "继续")}</button>
            <button onClick={dismissResume} style={{ padding: "8px 10px", borderRadius: 8, background: "none", border: "none", color: C.dim, fontSize: 12, cursor: "pointer" }}>{tr(lang, "Dismiss", "关闭")}</button>
          </div>
        )}
        {stage === "home" && <HomePage lang={lang} setLang={setLang} onStart={() => setStage("demographics")} onAdminClick={() => setAdminOpenedManually(true)} onLegalClick={() => setStage("legal")} />}
        {stage === "contact" && finalResults && (
          <ContactCapturePage lang={lang} setLang={setLang} demo={demo} setDemo={setDemo}
            onBack={() => setStage("results")}
            onNext={() => { saveContactDetails(); setStage(fullReportUnlocked ? "fullreport" : "checkout"); }} />
        )}
        {stage === "legal" && <LegalPage lang={lang} setLang={setLang} onBack={() => setStage("home")} />}
        {stage === "demographics" && <DemographicsPage lang={lang} setLang={setLang} demo={demo} setDemo={setDemo} onNext={() => { setPendingStep(0); setTransitionInfo(categoryInfoForStep(flowSteps, 0)); setStage("intake"); }} />}
        {stage === "intake" && (
          <>
            <TopBar lang={lang} setLang={setLang} showLogo={false} />
            <StickyHeader steps={flowSteps} step={step} lang={lang} />
            <LivelyProgress step={step} total={flowSteps.length} lang={lang} />
            <div style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column", justifyContent: "center", overflow: "auto", paddingBottom: 90 }}>
              <IntakeFlow steps={flowSteps} step={step} lang={lang} answers={answers} branchAnswers={branchAnswers} risk={risk} foundation={foundation} setFoundation={setFoundation} demoAge={demo.age}
                pickPersonal={pickPersonal} pickPersonalMulti={pickPersonalMulti} pickRisk={pickRisk} pickDomain={pickDomain} pickBranch={pickBranch} />
            </div>
            <NavBar step={step} total={flowSteps.length} isAnswered={isAnswered} goBack={goBack} goNext={goNext} needsManualButton={needsManualButton} requireAnswer={requireAnswer} lang={lang} />
          </>
        )}
        {stage === "results" && finalResults && (
          <ResultsScreen results={finalResults} demo={demo} saveState={saveState} restart={restart} lang={lang} setLang={setLang}
            onOpenFullReport={() => setStage(fullReportUnlocked ? "fullreport" : "contact")} />
        )}
        {stage === "checkout" && finalResults && (
          <CheckoutPage results={finalResults} demo={demo} lang={lang} setLang={setLang} onBack={() => setStage("results")}
            onUnlock={() => { setFullReportUnlocked(true); setStage("fullreport"); }} />
        )}
        {stage === "fullreport" && finalResults && (
          <FullReportPage results={finalResults} demo={demo} lang={lang} setLang={setLang} onBack={() => setStage("results")} />
        )}
      </div>
      )}
      <VitalitySummaryScreen data={vitalitySummary} lang={lang} onContinue={continueFromVitalitySummary} />
      <CategoryTransition info={transitionInfo} lang={lang} onContinue={confirmTransition} />
      {celebrating && <CelebrationScreen lang={lang} name={demo.name} onViewReport={viewReport} />}
      {!appReady && <LoadingSplash />}
    </div>
  );
}
